const runnerBase = process.env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = process.env.AUTOMATION_RUNNER_TOKEN;
if (!runnerBase) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');

const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};

const statusResponse = await fetch(`${runnerBase}/repo/status`, { headers });
if (!statusResponse.ok) {
  const body = await statusResponse.text();
  throw new Error(`Runner repo status failed: ${statusResponse.status} ${body}`);
}
const repoStatus = await statusResponse.json();

const timestamp = new Date().toISOString().replace(/[:]/g, '-');
const safeBranch = String(repoStatus.branch || 'unknown').replace(/[^a-zA-Z0-9._-]+/g, '-');
const reportRelativePath = `github-pr-summaries/${timestamp}-${safeBranch}.md`;

if (repoStatus.branch === 'main') {
  const reportContent = [
    '# GitHub PR And Commit Summary',
    '',
    `Generated: ${new Date().toISOString()}`,
    '',
    'Skipped because the repository is currently on main.',
  ].join('\n');

  await fetch(`${runnerBase}/reports/write`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
  });

  return [{ json: { generatedAt: new Date().toISOString(), skipped: true, reportRelativePath, repoStatus } }];
}

const summaryResponse = await fetch(`${runnerBase}/jobs`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ action: 'pr_summary', mode: 'sync', args: [] }),
});
const raw = await summaryResponse.text();
if (!summaryResponse.ok) {
  throw new Error(`pr_summary failed: ${summaryResponse.status} ${raw}`);
}
const result = raw ? JSON.parse(raw) : {};
const artifactPath = (result.stdout || '').trim().split(/\n/).filter(Boolean).at(-1) || 'docs/pr-reviews/<unknown>.md';

const reportContent = [
  '# GitHub PR And Commit Summary',
  '',
  `Generated: ${new Date().toISOString()}`,
  `Branch: ${repoStatus.branch}`,
  '',
  '## PR Context',
  '',
  repoStatus.pr ? `- PR #${repoStatus.pr.number}: ${repoStatus.pr.title} (${repoStatus.pr.url})` : '- No open PR detected for the current branch.',
  repoStatus.pr ? `- Review decision: ${repoStatus.pr.reviewDecision || 'none'}` : '',
  repoStatus.pr ? `- Merge state: ${repoStatus.pr.mergeStateStatus || 'unknown'}` : '',
  '',
  '## Summary Artifact',
  '',
  `- Repo-generated summary: ${artifactPath}`,
  '',
  '## Runner Result',
  '',
  '```json',
  JSON.stringify(result, null, 2),
  '```',
].filter(Boolean).join('\n');

const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (!writeResponse.ok) {
  const body = await writeResponse.text();
  throw new Error(`Runner report write failed: ${writeResponse.status} ${body}`);
}

return [{
  json: {
    generatedAt: new Date().toISOString(),
    artifactPath,
    reportRelativePath,
    repoStatus,
    result,
  },
}];
